    tpl=max(cs,key=len)
    my=min(y for y,_ in tpl); mx=min(x for _,x in tpl)
    hh=max(y for y,_ in tpl)-my+1; ww=max(x for _,x in tpl)-mx+1
    T=tuple(tuple(inp[my+r][mx+c] for c in range(ww)) for r in range(hh))
    marks=sorted([min(c) for c in cs if c is not tpl])
    out=[row[:] for row in inp]
    for iy,ix in marks:
        ly,iy_=iy+dy; lc,ix_=(ix+dx)%(W)
        for r in range(hh):
            for cc in range(ww):
                yy_,xx_=iy_+r,lc+cc
                if 0<=yy_<H and 0<=xx_<W: out[yy_][xx_]=T[r][cc]
    return out==o,out

