def run(n):
    inp=G[f'Demo pair {n} input']; o=G[f'Demo pair {n} output']
    H,W=len(inp),len(inp[0]); cs=comps(inp,H,W)
    tpl=max(cs,key=len)
    my=min(y for y,_ in tpl); mx=min(x for _,x in tpl)
    hh=max(y for y,_ in tpl)-my+1; ww=max(x for _,x in tpl)-mx+1
    T=list(map(list,map(int,tuple(tuple(inp[my+r][mx+c] for c in range(ww)) for r in range(hh)))))
    marks=sorted([min(c) for c in cs if c is not tpl])
    # All deltas that keep stamp in bounds for ANY marker
    D=set()
    for iy,ix in marks:
        for dy in range(-hh, H-hh+1):
            for dx in range(-ww, W-ww+1):
                D.add((dy,dx))
    # Brute force: assign one delta per marker from D, later-overwrite, match output
    import itertools
    sols=[]
    for assg in itertools.product(D, repeat=len(marks)):
        out=[r[:] for r in inp]
        okm=True
        for k,a in zip(marks,assg):
            iy,ix=k; dy,dx=a
            for r in range(hh):
                for c in range(ww):
                    yy_,xx_=iy+dy+r,ix+dx+c
                    if 0<=yy_<H and 0<=xx_<W: out[yy_][xx_]=T[r][c]
        if out==o: sols.append(assg)
    return sols,hh,ww,T,marks

